-- LeadFlow AI database schema (generated by scripts/export_docs.py - do not edit by hand)


-- ============================================================
-- SQLite (default)
-- ============================================================

CREATE TABLE admin_users (
	id INTEGER NOT NULL, 
	username VARCHAR(50) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	is_active BOOLEAN DEFAULT '1' NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);

CREATE UNIQUE INDEX ix_admin_users_username ON admin_users (username);


CREATE TABLE enquiries (
	id INTEGER NOT NULL, 
	customer_name VARCHAR(150) NOT NULL, 
	phone VARCHAR(20), 
	email VARCHAR(254), 
	message TEXT NOT NULL, 
	source VARCHAR(50) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	ai_status VARCHAR(20) NOT NULL, 
	priority VARCHAR(10), 
	priority_reason TEXT, 
	needs_manual_review BOOLEAN NOT NULL, 
	assigned_to_id INTEGER, 
	assigned_at DATETIME, 
	duplicate_of_id INTEGER, 
	duplicate_reason VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_enquiry_status CHECK (status IN ('New','In Progress','Converted','Closed')), 
	CONSTRAINT ck_enquiry_ai_status CHECK (ai_status IN ('pending','processing','completed','failed')), 
	CONSTRAINT ck_enquiry_priority CHECK (priority IS NULL OR priority IN ('Low','Medium','High')), 
	FOREIGN KEY(assigned_to_id) REFERENCES admin_users (id) ON DELETE SET NULL, 
	FOREIGN KEY(duplicate_of_id) REFERENCES enquiries (id) ON DELETE SET NULL
);

CREATE INDEX ix_enquiries_assigned_to_id ON enquiries (assigned_to_id);

CREATE INDEX ix_enquiries_created_at ON enquiries (created_at);

CREATE INDEX ix_enquiries_email ON enquiries (email);

CREATE INDEX ix_enquiries_phone ON enquiries (phone);

CREATE INDEX ix_enquiries_priority ON enquiries (priority);

CREATE INDEX ix_enquiries_status_created ON enquiries (status, created_at);


CREATE TABLE ai_analysis (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER NOT NULL, 
	service_category VARCHAR(50) NOT NULL, 
	customer_location VARCHAR(150), 
	budget NUMERIC(14, 2), 
	currency VARCHAR(3), 
	urgency VARCHAR(10), 
	project_timeline VARCHAR(150), 
	project_requirements JSON NOT NULL, 
	missing_information JSON NOT NULL, 
	summary TEXT, 
	customer_intent VARCHAR(200), 
	sentiment VARCHAR(20), 
	detected_language VARCHAR(50), 
	confidence_score FLOAT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_analysis_category CHECK (service_category IN ('Website Development','Mobile Application Development','AI Software Development','Digital Marketing','E-commerce Development','Custom Software Development','Other Services')), 
	CONSTRAINT ck_analysis_conf CHECK (confidence_score IS NULL OR (confidence_score >= 0 AND confidence_score <= 1)), 
	UNIQUE (enquiry_id), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE
);

CREATE INDEX ix_ai_analysis_service_category ON ai_analysis (service_category);


CREATE TABLE ai_responses (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER NOT NULL, 
	generated_response TEXT NOT NULL, 
	edited_response TEXT, 
	followup_questions JSON NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (enquiry_id), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE
);


CREATE TABLE ai_usage (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER, 
	provider VARCHAR(20) NOT NULL, 
	model_name VARCHAR(80) NOT NULL, 
	task VARCHAR(40) NOT NULL, 
	attempt INTEGER NOT NULL, 
	input_tokens INTEGER NOT NULL, 
	output_tokens INTEGER NOT NULL, 
	response_time FLOAT NOT NULL, 
	estimated_cost NUMERIC(10, 6) NOT NULL, 
	execution_status VARCHAR(10) NOT NULL, 
	error_message VARCHAR(300), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_usage_status CHECK (execution_status IN ('success','failed')), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE SET NULL
);

CREATE INDEX ix_ai_usage_created_at ON ai_usage (created_at);

CREATE INDEX ix_ai_usage_enquiry_id ON ai_usage (enquiry_id);

CREATE INDEX ix_ai_usage_provider ON ai_usage (provider);


CREATE TABLE communications (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER NOT NULL, 
	channel VARCHAR(10) NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	recipient VARCHAR(400) NOT NULL, 
	subject VARCHAR(300), 
	body TEXT, 
	status VARCHAR(10) NOT NULL, 
	error VARCHAR(300), 
	sent_by_id INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_comm_channel CHECK (channel IN ('email','whatsapp')), 
	CONSTRAINT ck_comm_kind CHECK (kind IN ('customer_reply','team_notification')), 
	CONSTRAINT ck_comm_status CHECK (status IN ('sent','failed','opened','skipped')), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE, 
	FOREIGN KEY(sent_by_id) REFERENCES admin_users (id) ON DELETE SET NULL
);

CREATE INDEX ix_communications_created_at ON communications (created_at);

CREATE INDEX ix_communications_enquiry_id ON communications (enquiry_id);


CREATE TABLE followups (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER NOT NULL, 
	suggested_action TEXT NOT NULL, 
	suggested_date DATETIME, 
	status VARCHAR(10) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_followup_status CHECK (status IN ('Pending','Done','Dismissed')), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE
);

CREATE INDEX ix_followups_enquiry_id ON followups (enquiry_id);


CREATE TABLE lead_scores (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER NOT NULL, 
	total_score INTEGER NOT NULL, 
	budget_score INTEGER NOT NULL, 
	requirement_clarity_score INTEGER NOT NULL, 
	urgency_score INTEGER NOT NULL, 
	service_relevance_score INTEGER NOT NULL, 
	engagement_score INTEGER NOT NULL, 
	lead_temperature VARCHAR(10) NOT NULL, 
	scoring_explanation TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_score_total CHECK (total_score BETWEEN 0 AND 100), 
	CONSTRAINT ck_score_temp CHECK (lead_temperature IN ('Hot','Warm','Cold')), 
	UNIQUE (enquiry_id), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE
);

CREATE INDEX ix_lead_scores_lead_temperature ON lead_scores (lead_temperature);


CREATE TABLE workflow_logs (
	id INTEGER NOT NULL, 
	enquiry_id INTEGER NOT NULL, 
	workflow_step VARCHAR(80) NOT NULL, 
	execution_status VARCHAR(10) NOT NULL, 
	message TEXT, 
	execution_time FLOAT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_wf_status CHECK (execution_status IN ('started','success','failed','skipped')), 
	FOREIGN KEY(enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE
);

CREATE INDEX ix_wf_enquiry_created ON workflow_logs (enquiry_id, created_at);



